public sealed class PreviaInterfaceTests
{
    [AvaloniaFact(DisplayName = "VP01 | Prévia Avalonia Moderno Claro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario01() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Moderno,ModoVisual.Claro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Light,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Moderno-Claro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Moderno-Claro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Moderno-Claro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP02 | Prévia Avalonia Moderno Escuro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario02() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Moderno,ModoVisual.Escuro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Dark,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Moderno-Escuro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Moderno-Escuro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Moderno-Escuro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP03 | Prévia Avalonia Tecnologico Claro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario03() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Tecnologico,ModoVisual.Claro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Light,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Tecnologico-Claro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Tecnologico-Claro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Tecnologico-Claro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP04 | Prévia Avalonia Tecnologico Escuro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario04() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Tecnologico,ModoVisual.Escuro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Dark,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Tecnologico-Escuro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Tecnologico-Escuro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Tecnologico-Escuro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP05 | Prévia Avalonia Acolhedor Claro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario05() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Claro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Light,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Acolhedor-Claro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Acolhedor-Claro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Acolhedor-Claro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP06 | Prévia Avalonia Acolhedor Escuro | Janela controles e captura refletem a combinação em tempo real")]
    public void Cenario06() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);var r=ResolvedorAparencia.Resolver(t.Janela.AparenciaAtual.Preferencias).Recursos;Assert.Equal(r["PageBackground"],ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(r["ControlBackground"],ApoioAparencia.Cor(t.Campo<TextBox>("TxtTitulo").Background));Assert.Equal(ThemeVariant.Dark,t.Janela.ActualThemeVariant);t.Clicar("NavInicio");ApoioAparencia.Capturar(t,"Acolhedor-Escuro-inicio");t.Clicar("NavBacklog");ApoioAparencia.Capturar(t,"Acolhedor-Escuro-biblioteca");t.Clicar("NavAparencia");ApoioAparencia.Capturar(t,"Acolhedor-Escuro-aparencia"); }
    [AvaloniaFact(DisplayName = "VP07 | Cor do fundo principal em tempo real | Brush da janela atualiza sem recriar janela")]
    public void Cenario07() { using var t=new TelaTeste();t.Clicar("NavAparencia");var janela=t.Janela;ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text="#163a63";ApoioAparencia.Render(t);Assert.Same(janela,t.Janela);Assert.Equal("#163A63",ApoioAparencia.Cor(t.Janela.Background));Assert.Equal("#163A63",ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text); }
    [AvaloniaFact(DisplayName = "VP08 | Texto incompleto durante digitação | Mantém última cor e não grava estado intermediário")]
    public void Cenario08() { var a=new AparenciaSimulada();using var t=new TelaTeste(aparencia:a.Criar());t.Clicar("NavAparencia");var e=ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal);e.Campo.Text="#123456";var n=a.Gravacoes;foreach(var texto in new[]{"#","#12","#12345","#12GG34"})e.Campo.Text=texto;Assert.Equal(n,a.Gravacoes);Assert.Equal("#123456",ApoioAparencia.Cor(e.Amostra.Background));Assert.Contains("#RRGGBB",e.Mensagem.Text!);Assert.Equal("#123456",ApoioAparencia.Cor(t.Janela.Background)); }
    [AvaloniaFact(DisplayName = "VP09 | Paleta sincroniza campo e amostra | Escolha pronta aplica código e prévia correspondente")]
    public void Cenario09() { using var t=new TelaTeste();t.Clicar("NavAparencia");var e=ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal);ApoioAparencia.Render(t);var b=e.GetVisualDescendants().OfType<Button>().First(x=>ToolTip.GetTip(x)?.ToString()=="#163A63");b.RaiseEvent(new Avalonia.Interactivity.RoutedEventArgs(Button.ClickEvent));Assert.Equal("#163A63",e.Campo.Text);Assert.Equal("#163A63",ApoioAparencia.Cor(e.Amostra.Background));Assert.Equal("#163A63",ApoioAparencia.Cor(t.Janela.Background)); }
    [AvaloniaFact(DisplayName = "VP10 | Hexadecimal arbitrário sincroniza amostra | Cor fora da paleta é mostrada e normalizada")]
    public void Cenario10() { using var t=new TelaTeste();t.Clicar("NavAparencia");var e=ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal);e.Campo.Text=" #f7a1b3 ";Assert.Equal("#F7A1B3",e.Campo.Text);Assert.Equal("#F7A1B3",ApoioAparencia.Cor(e.Amostra.Background)); }
    [AvaloniaFact(DisplayName = "VP11 | Aviso de contraste na própria tela | Ajuste explícito mantém campo solicitado e texto efetivo legível")]
    public void Cenario11() { using var t=new TelaTeste();t.Clicar("NavAparencia");ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text="#FFFFFF";var e=ApoioAparencia.Editor(t,ElementoCor.TextoPrincipal);e.Campo.Text="#FFFFFF";Assert.Contains("ajustado",e.Ajuste.Text!);Assert.Equal("#FFFFFF",e.Campo.Text);Assert.Equal("#000000",ApoioAparencia.Cor(t.Janela.Foreground)); }
    [AvaloniaFact(DisplayName = "VP12 | Prévia com formulário preenchido | Título review e navegação não são perdidos")]
    public void Cenario12() { using var t=new TelaTeste(new[]{PastaTeste.Jogo()});t.Editar();t.Campo<TextBox>("TxtReview").Text="Rascunho pessoal";ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);t.Clicar("NavCadastro");Assert.Equal("Rascunho pessoal",t.Campo<TextBox>("TxtReview").Text);Assert.Equal("Jogo simulado",t.Campo<TextBox>("TxtTitulo").Text); }
    [AvaloniaFact(DisplayName = "VP13 | Nova janela recebe tema carregado | Preferência persistida é aplicada ao abrir novamente")]
    public void Cenario13() { var a=new AparenciaSimulada();using(var t=new TelaTeste(aparencia:a.Criar())){ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text="#123456";}using var b=new TelaTeste(aparencia:a.Criar());Assert.Equal(TemaVisual.Acolhedor,b.Janela.AparenciaAtual.Preferencias.Tema);Assert.Equal("#123456",ApoioAparencia.Cor(b.Janela.Background)); }
    [AvaloniaFact(DisplayName = "VP14 | Janela já aberta atualiza recursos compartilhados | Troca em segunda janela chega à primeira janela")]
    public void Cenario14() { var a=new AparenciaSimulada();using var t=new TelaTeste(aparencia:a.Criar());using var b=new TelaTeste(aparencia:a.Criar());ApoioAparencia.Tema(b,TemaVisual.Tecnologico,ModoVisual.Escuro);Assert.Equal(ApoioAparencia.Cor(b.Janela.Background),ApoioAparencia.Cor(t.Janela.Background));Assert.Equal(ThemeVariant.Dark,t.Janela.ActualThemeVariant); }
    [AvaloniaFact(DisplayName = "VP15 | Falha ao salvar pela interface | Prévia funciona e mensagem não afirma sucesso")]
    public void Cenario15() { var a=new AparenciaSimulada{FalhaSalvar=new IOException()};using var t=new TelaTeste(aparencia:a.Criar());ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);Assert.Contains("não pôde ser salva",t.Campo<TextBlock>("TxtEstadoAparencia").Text!);Assert.True(t.Campo<Button>("BtnRepetirSalvarAparencia").IsVisible); }
    [AvaloniaFact(DisplayName = "VP16 | Retry de gravação pela interface | Grava preferências atuais e encerra estado pendente")]
    public void Cenario16() { var a=new AparenciaSimulada{FalhaSalvar=new IOException()};using var t=new TelaTeste(aparencia:a.Criar());ApoioAparencia.Tema(t,TemaVisual.Tecnologico,ModoVisual.Escuro);a.FalhaSalvar=null;t.Clicar("BtnRepetirSalvarAparencia");Assert.False(t.Campo<Button>("BtnRepetirSalvarAparencia").IsVisible);Assert.Equal(TemaVisual.Tecnologico,a.Preferencias.Tema);Assert.Equal(ModoVisual.Escuro,a.Preferencias.Modo); }
    [AvaloniaFact(DisplayName = "VP17 | Restaurar global exige confirmação | Solicitar não altera as cores antes de confirmar")]
    public void Cenario17() { using var t=new TelaTeste();ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);t.Clicar("BtnRestaurarAparencia");Assert.True(t.Campo<Border>("ConfirmacaoRestaurarAparencia").IsVisible);Assert.Equal(TemaVisual.Acolhedor,t.Janela.AparenciaAtual.Preferencias.Tema); }
    [AvaloniaFact(DisplayName = "VP18 | Cancelar restauração global | Mantém as escolhas e fecha confirmação")]
    public void Cenario18() { using var t=new TelaTeste();ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);t.Clicar("BtnRestaurarAparencia");t.Clicar("BtnCancelarRestaurarAparencia");Assert.False(t.Campo<Border>("ConfirmacaoRestaurarAparencia").IsVisible);Assert.Equal(TemaVisual.Acolhedor,t.Janela.AparenciaAtual.Preferencias.Tema); }
    [AvaloniaFact(DisplayName = "VP19 | Confirmar restauração global | Moderno claro é aplicado imediatamente")]
    public void Cenario19() { using var t=new TelaTeste();ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);t.Clicar("BtnRestaurarAparencia");t.Clicar("BtnConfirmarRestaurarAparencia");Assert.Equal(TemaVisual.Moderno,t.Janela.AparenciaAtual.Preferencias.Tema);Assert.Equal(0,t.Campo<ComboBox>("CmbModo").SelectedIndex);Assert.False(t.Campo<Border>("ConfirmacaoRestaurarAparencia").IsVisible); }
    [AvaloniaFact(DisplayName = "VP20 | Restaurar ativo pela interface | Campos e amostra retornam aos padrões e outro modo permanece")]
    public void Cenario20() { using var t=new TelaTeste();ApoioAparencia.Tema(t,TemaVisual.Moderno,ModoVisual.Claro);ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text="#123456";ApoioAparencia.Tema(t,TemaVisual.Moderno,ModoVisual.Escuro);ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text="#654321";t.Clicar("BtnRestaurarCores");ApoioAparencia.Tema(t,TemaVisual.Moderno,ModoVisual.Claro);Assert.Equal("#123456",ApoioAparencia.Editor(t,ElementoCor.FundoPrincipal).Campo.Text); }
    [AvaloniaFact(DisplayName = "VP21 | Nome público e recursos técnicos | Interface usa nome aprovado sem slogan ou troca de namespace")]
    public void Cenario21() { using var t=new TelaTeste();Assert.Equal("Minhas Realizações",t.Janela.Title);Assert.Contains(t.Janela.GetVisualDescendants().OfType<TextBlock>(),x=>x.Text=="Minhas Realizações");Assert.DoesNotContain(t.Janela.GetVisualDescendants().OfType<TextBlock>(),x=>x.Text is "Backlog" or "MANAGER" or "Sua coleção, no seu ritmo");Assert.Equal("BacklogManager",typeof(MainWindow).Namespace); }
    [AvaloniaFact(DisplayName = "VP22 | Aparência no tamanho mínimo | Todos os grupos ficam alcançáveis pela rolagem")]
    public void Cenario22() { using var t=new TelaTeste();t.Clicar("NavAparencia");t.Janela.Width=900;t.Janela.Height=660;ApoioAparencia.Render(t);Assert.Equal(13,t.Campo<WrapPanel>("EditoresCores").Children.Count);ApoioAparencia.Capturar(t,"aparencia-minima-topo");t.Campo<ScrollViewer>("PaginaAparencia").Offset=new Vector(0,10000);ApoioAparencia.Capturar(t,"aparencia-minima-fim");Assert.True(ApoioAparencia.Editor(t,ElementoCor.TextoSecundario).Bounds.Height>0); }
    [AvaloniaFact(DisplayName = "VP23 | Prévia mantém biblioteca e coleções | Aparência não grava registros nem seus vínculos")]
    public void Cenario23() { using var p=new PastaTeste();var caminho=Path.Combine(p.Pasta,"aparencia.json");var s=new ServicoAparencia(new ArmazenamentoAparenciaJson(caminho));using var t=new TelaTeste(new[]{PastaTeste.Jogo()},aparencia:s,criarColecoes:b=>new BacklogManager.Services.ServicoColecoes(new ArmazenamentoColecoesJson(Path.Combine(p.Pasta,"colecoes.json")),b));t.Clicar("NavColecoes");t.Campo<TextBox>("TxtNomeColecao").Text="Favoritos";t.Clicar("BtnCriarColecao");t.Campo<ComboBox>("CmbObraColecao").SelectedIndex=0;t.Clicar("BtnAdicionarObraColecao");var bib=File.ReadAllBytes(t.Pasta.Arquivo);var col=File.ReadAllBytes(Path.Combine(p.Pasta,"colecoes.json"));ApoioAparencia.Tema(t,TemaVisual.Acolhedor,ModoVisual.Escuro);ApoioAparencia.Editor(t,ElementoCor.FundoCartao).Campo.Text="#123456";t.Clicar("BtnRestaurarCores");Assert.Equal(bib,File.ReadAllBytes(t.Pasta.Arquivo));Assert.Equal(col,File.ReadAllBytes(Path.Combine(p.Pasta,"colecoes.json")));t.Clicar("NavColecoes");Assert.Single(t.Campo<ListBox>("ListaObrasColecao").Items); }
}
